// Window = from the end of the last successful production run until now - lag.
// Static data is only persisted on production (active) executions; manual runs use the default window.
const cfg = $('Config').first().json;
const sd = $getWorkflowStaticData('global');
const now = new Date();
const until = new Date(now.getTime() - cfg.lag_minutes * 60000);
let since = sd.lastUntil ? new Date(sd.lastUntil) : new Date(until.getTime() - cfg.default_window_hours * 3600000);
const maxSpan = 7 * 24 * 3600000; // Ada export allows max 7 days per request
if (until - since > maxSpan) since = new Date(until.getTime() - maxSpan);
const iso = d => d.toISOString().replace(/\.\d{3}Z$/, 'Z');
return [{ json: { since: iso(since), until: iso(until), messages_until: iso(now), base: cfg.ada_base_url.replace(/\/$/, '') } }];

// Keeps only conversations Aura handled alone (no handoff, no human agent message, not a test)
// and builds compact transcripts, grouped in batches for Nova.
const cfg = $('Config').first().json;
const win = $('Compute Window').first().json;
const get = (o, path) => path.split('.').reduce((a, k) => (a == null ? a : a[k]), o);
const pick = (o, ...paths) => { for (const p of paths) { const v = get(o, p); if (v !== undefined && v !== null && v !== '') return v; } return undefined; };
const rows = (node) => $(node).all().flatMap(i => Array.isArray(i.json.data) ? i.json.data : (Array.isArray(i.json) ? i.json : []));

const convs = rows('Get Ada Conversations');
const msgs = rows('Get Ada Messages');

const byConv = {};
for (const m of msgs) {
  const cid = pick(m, 'conversation_id', 'conversationId', 'conversation._id');
  if (cid) (byConv[cid] ||= []).push(m);
}
const textOf = (m) => {
  const d = pick(m, 'message_data', 'messageData') || {};
  let t = pick(d, 'text', 'body', 'title', 'description', 'label') ?? pick(m, 'text', 'body') ?? '';
  if (typeof t !== 'string') t = JSON.stringify(t);
  return t.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
};
const roleOf = (m) => {
  let s = pick(m, 'sender', 'author.role', 'role', 'source', 'sender_type');
  if (s && typeof s === 'object') s = pick(s, 'type', 'role', '_type') || '';
  s = String(s || '').toLowerCase();
  // Bot/AI first: Ada's AI agent can be labelled "ai_agent"/"bot" and must not count as a human handoff.
  if (/^(bot|ada|ai|ai_?agent|generative|assistant|system)/.test(s)) return 'AURA';
  if (/chatter|end.?user|customer|^user/.test(s)) return 'USER';
  if (/human|live.?agent|^agent$|support_agent/.test(s)) return 'AGENT';
  return 'AURA';
};
const ts = (m) => new Date(pick(m, 'date_created', 'created_at', 'date') || 0).getTime();

const stats = { total: convs.length, escalated: 0, test: 0, no_messages: 0, no_user_message: 0, contained: 0, truncated: 0 };
const out = [];
for (const c of convs) {
  const id = pick(c, '_id', 'id', 'conversation_id');
  if (!id) continue;
  if (pick(c, 'is_test', 'test') === true) { stats.test++; continue; }
  const ms = (byConv[id] || []).sort((a, b) => ts(a) - ts(b));
  const escalated = pick(c, 'is_escalated', 'escalated', 'handoff', 'is_handed_off') === true || ms.some(m => roleOf(m) === 'AGENT');
  if (escalated) { stats.escalated++; continue; }
  if (!ms.length) { stats.no_messages++; continue; }
  if (!ms.some(m => roleOf(m) === 'USER' && textOf(m))) { stats.no_user_message++; continue; }
  stats.contained++;
  let t = ms.map(m => [roleOf(m), textOf(m)]).filter(([, x]) => x).map(([r, x]) => r + ': ' + x).join('\n');
  const max = cfg.max_chars_per_conversation;
  if (t.length > max) t = t.slice(0, Math.floor(max * 0.4)) + '\n[…]\n' + t.slice(-Math.floor(max * 0.6));
  const csat = pick(c, 'csat.score', 'csat.rating', 'csat_score');
  out.push({ id, csat: (typeof csat === 'number' || typeof csat === 'string') ? csat : null, transcript: t });
}
if (out.length > cfg.max_conversations) { stats.truncated = out.length - cfg.max_conversations; out.length = cfg.max_conversations; }

if (!out.length) {
  // Fail loudly with diagnostics instead of ending silently (shows in n8n and in the error alert).
  const keys = (o) => o ? Object.keys(o).slice(0, 25).join(', ') : 'none';
  const firstConvPage = $('Get Ada Conversations').first().json;
  throw new Error('No contained conversations to analyze. stats=' + JSON.stringify(stats) +
    ' | conv page keys: ' + keys(firstConvPage) + ' | first conversation keys: ' + keys(convs[0]) +
    ' | messages: ' + msgs.length + ', first message keys: ' + keys(msgs[0]) +
    ' | sample sender: ' + JSON.stringify(msgs[0] ? (msgs[0].sender ?? msgs[0].author ?? msgs[0].role) : null));
}
const batches = [];
for (let i = 0; i < out.length; i += cfg.batch_size) batches.push(out.slice(i, i + cfg.batch_size));
return batches.map((b, k) => ({ json: { batch_no: k + 1, n_batches: batches.length, stats, window: win, conversations: b } }));

