// Pass the classified items back to the loop; if Nova failed on this batch, count it instead of losing the run.
const batch = $('Loop Over Batches').item.json;
const items = $json.output && Array.isArray($json.output.items) ? $json.output.items : null;
if (!items) return { json: { batch_no: batch.batch_no, failed: true, n: batch.conversations.length, error: String($json.error || 'no structured output').slice(0, 300) } };
const known = new Set(batch.conversations.map(c => c.id));
return { json: { batch_no: batch.batch_no, failed: false, items: items.filter(i => known.has(i.id)), csat: Object.fromEntries(batch.conversations.filter(c => c.csat != null).map(c => [c.id, c.csat])) } };

// Aggregates all batches into the KPIs used by the Slack message, the insights agent and the sheet.
const cfg = $('Config').first().json;
const win = $('Compute Window').first().json;
const stats = $('Build Batches').first().json.stats;
const batches = $input.all().map(i => i.json);
const items = batches.flatMap(b => b.items || []);
const csat = Object.assign({}, ...batches.map(b => b.csat || {}));
const failedConvs = batches.filter(b => b.failed).reduce((a, b) => a + (b.n || 0), 0);

const real = items.filter(i => i.outcome !== 'no_real_ask');
const n = real.length;
const count = (arr, key) => arr.reduce((a, i) => { a[i[key]] = (a[i[key]] || 0) + 1; return a; }, {});
const pct = (x) => n ? Math.round((x / n) * 100) : 0;
const outcomes = count(real, 'outcome');
const sentiment = count(real, 'sentiment');
const notOk = real.filter(i => ['open_problem', 'explicit_complaint', 'asked_for_human'].includes(i.outcome));
const causes = count(notOk.filter(i => i.open_problem_cause !== 'none'), 'open_problem_cause');
const complaints = count(real.filter(i => i.outcome === 'explicit_complaint' && i.complaint_type !== 'none'), 'complaint_type');
const topics = Object.entries(count(notOk, 'topic')).sort((a, b) => b[1] - a[1]).slice(0, 8);
const link = (id) => `${win.base}/insights/conversations/${id}`;
const riskOrder = { fraud: 0, legal_threat: 1, money_missing: 2, account_blocked: 3, churn: 4 };
const risks = real.filter(i => i.risk && i.risk !== 'none')
  .sort((a, b) => (riskOrder[a.risk] ?? 9) - (riskOrder[b.risk] ?? 9))
  .map(i => ({ id: i.id, link: link(i.id), risk: i.risk, risk_detail: i.risk_detail || '', topic: i.topic, quote: i.quote || '' }));
const auraIssues = real.filter(i => i.aura_issue).map(i => ({ id: i.id, topic: i.topic, outcome: i.outcome, aura_issue: i.aura_issue, quote: i.quote || '' }));

const summary = {
  window: { since: win.since, until: win.until },
  totals: { conversations: stats.total, handed_off: stats.escalated, contained: stats.contained, real_ask: n,
            no_real_ask: items.length - n + stats.no_user_message, failed_to_classify: failedConvs, not_analyzed_over_cap: stats.truncated },
  outcomes, outcomes_pct: Object.fromEntries(Object.entries(outcomes).map(([k, v]) => [k, pct(v)])),
  sentiment_pct: Object.fromEntries(Object.entries(sentiment).map(([k, v]) => [k, pct(v)])),
  open_problem_causes: causes, complaint_types: complaints, top_problem_topics: topics,
  risk_cases: risks.length, aura_issue_cases: auraIssues.length
};
const prev = $getWorkflowStaticData('global').prevSummary || null;
const notable = notOk.concat(real.filter(i => i.aura_issue && !notOk.includes(i)))
  .slice(0, 70).map(i => ({ topic: i.topic, outcome: i.outcome, cause: i.open_problem_cause, complaint: i.complaint_type, risk: i.risk, quote: i.quote, aura_issue: i.aura_issue }));
const rows = items.map(i => ({
  run_until: win.until, conversation_id: i.id, link: link(i.id), language: i.language || '', topic: i.topic, sentiment: i.sentiment,
  outcome: i.outcome, open_problem_cause: i.open_problem_cause, complaint_type: i.complaint_type, risk: i.risk,
  risk_detail: i.risk_detail || '', quote: i.quote || '', aura_issue: i.aura_issue || '', csat: csat[i.id] ?? ''
}));
return [{ json: { summary, prev, notable, risks, rows } }];

