// Builds the Slack summary and advances the window (static data persists only on production runs).
const cfg = $('Config').first().json;
const { summary: s, prev, risks } = $('Build Report Data').first().json;
const ins = $json.output || null;
const z = 'America/Bogota';
const f = (iso, fmt) => DateTime.fromISO(iso).setZone(z).setLocale('es').toFormat(fmt);
const sameDay = f(s.window.since, 'yyyy-LL-dd') === f(s.window.until, 'yyyy-LL-dd');
const win = sameDay ? `${f(s.window.since, 'd LLL')}, ${f(s.window.since, 'HH:mm')}–${f(s.window.until, 'HH:mm')}`
                    : `${f(s.window.since, 'd LLL HH:mm')} – ${f(s.window.until, 'd LLL HH:mm')}`;
const o = s.outcomes || {}, p = s.outcomes_pct || {};
const pad = (x, w) => String(x).padStart(w);
const row = (label, key) => `${label.padEnd(34)}${pad(o[key] || 0, 5)}${pad((p[key] || 0) + '%', 6)}`;
const delta = (key) => {
  if (!prev || !prev.outcomes_pct) return '';
  const d = (p[key] || 0) - (prev.outcomes_pct[key] || 0);
  return d === 0 ? '=' : (d > 0 ? '+' : '−') + Math.abs(d) + ' pp';
};
const L = { product_limit: 'límite del producto', aura_missing_data: 'Aura no tenía el dato', aura_misunderstood: 'Aura no entendió', should_have_escalated: 'debía escalar', product_bug: 'bug del producto',
            product_delay: 'producto · demora', product_unavailable: 'producto · no disponible', support_aura: 'soporte · Aura', support_team: 'soporte · equipo',
            positive: 'positivo', neutral: 'neutral', negative: 'negativo', frustrated: 'frustrado',
            money_missing: 'dinero sin llegar', fraud: 'posible fraude', legal_threat: 'amenaza legal', churn: 'quiere irse/cerrar', account_blocked: 'cuenta bloqueada' };
const list = (obj) => Object.entries(obj || {}).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${L[k] || k} ${v}`).join(' · ') || '—';

const lines = [];
lines.push(`*🤖 Aura · conversaciones sin handoff* · ${win} (COL)`);
lines.push(`_${s.totals.real_ask} con consulta real · ${s.totals.handed_off} pasaron a agente (no incluidas)_`);
lines.push('```');
lines.push(`${'Resultado'.padEnd(34)}${pad('Casos', 5)}${pad('%', 6)}`);
lines.push(row('Resuelto con Aura', 'resolved'));
lines.push(row('El usuario no continuó', 'user_did_not_continue'));
lines.push(row('Problema abierto', 'open_problem'));
lines.push(row('Queja explícita', 'explicit_complaint'));
lines.push(row('Pidió un agente', 'asked_for_human'));
lines.push('```');
if (prev) lines.push(`*vs. revisión anterior:* resuelto ${delta('resolved')} · quejas ${delta('explicit_complaint')} · pidió agente ${delta('asked_for_human')}`);
lines.push(`*Sentimiento:* ${Object.entries(s.sentiment_pct || {}).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${v}% ${L[k] || k}`).join(' · ')}`);
lines.push(`*Quejas por tipo:* ${list(s.complaint_types)}`);
lines.push(`*Por qué quedaron abiertos:* ${list(s.open_problem_causes)}`);
if (ins) {
  lines.push('');
  lines.push(ins.resumen);
  lines.push('');
  lines.push('*🔧 Oportunidades de mejora*');
  (ins.hallazgos || []).forEach((h, k) => lines.push(`${k + 1}. *${h.titulo}* (${h.impacto}): ${h.detalle}`));
}
if (risks.length) {
  lines.push('');
  lines.push(`*⚠️ Para revisar con el equipo (${risks.length})*`);
  risks.slice(0, cfg.max_risk_cases_in_slack).forEach(r => lines.push(`• <${r.link}|${L[r.risk] || r.risk}> · ${r.topic}${r.risk_detail ? ' · ' + r.risk_detail : ''}`));
  if (risks.length > cfg.max_risk_cases_in_slack) lines.push(`_…y ${risks.length - cfg.max_risk_cases_in_slack} más en la hoja._`);
}
const notes = [];
if (s.totals.failed_to_classify) notes.push(`${s.totals.failed_to_classify} conversaciones no se pudieron clasificar`);
if (s.totals.not_analyzed_over_cap) notes.push(`${s.totals.not_analyzed_over_cap} quedaron fuera por el límite de ${cfg.max_conversations}`);
if (!ins) notes.push('no se generaron los hallazgos (falló Nova · Write Insights)');
if (notes.length) lines.push(`\n_Nota: ${notes.join('; ')}._`);

const sd = $getWorkflowStaticData('global');
sd.lastUntil = s.window.until;
sd.prevSummary = { window: s.window, outcomes_pct: s.outcomes_pct, sentiment_pct: s.sentiment_pct, totals: s.totals };
return [{ json: { channel: cfg.slack_channel, text: lines.join('\n') } }];
